/// The failure strain of the library material with this `id` (`None` for a user-added material).
pub fn failure_strain(id: &str) -> Option<FailureStrain> {
    let i = TABLE.binary_search_by(|r| r.0.cmp(id)).ok()?;
    let (_, value, basis, m, a) = TABLE[i];
    let basis = match basis {
        0 => Basis::Validated,
        1 => Basis::Family,
        2 => Basis::Bound,
        3 => Basis::Default,
        4 => Basis::Capped,
        5 => Basis::Typical,
        _ => Basis::NotApplicable,
    };
    Some(FailureStrain { value: value as f64, basis, multiplier: m as f64, elongation_pct: a as f64 })
}

/// Number of entries.
pub fn len() -> usize {
    TABLE.len()
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::materials::builtin_catalog;

    #[test]
    fn every_library_material_has_a_failure_strain_in_range() {
        let mut n = 0;
        for m in builtin_catalog() {
            let f = failure_strain(m.id).unwrap_or_else(|| panic!("no failure strain for {}", m.id));
            if f.basis == Basis::NotApplicable {
                assert_eq!(m.id, "cfrp_qi");
                continue;
            }
            assert!((0.0299..=0.5001).contains(&f.value), "{}: {}", m.id, f.value);
            n += 1;
        }
        assert_eq!(n + 1, len());
        assert!(failure_strain("nonexistent").is_none());
    }

    #[test]
    fn the_rule_is_multiplier_times_ln_one_plus_elongation() {
        for m in builtin_catalog() {
            let f = failure_strain(m.id).unwrap();
            if matches!(f.basis, Basis::Validated | Basis::Family | Basis::Bound) {
                let want = (f.multiplier * (1.0 + f.elongation_pct / 100.0).ln()).clamp(0.03, 0.50);
                assert!((f.value - want).abs() < 6e-4, "{}: {} vs {want}", m.id, f.value);
                assert!(f.multiplier <= 2.0, "{}: no multiplier beyond the bearing-validated 2.0", m.id);
            }
        }
    }

    #[test]
    fn the_validated_aluminium_alloys_follow_the_naca_calibration() {
        // 7075-T6 bar (A = 11.2 %): the NACA TN 1503 inverse calibration gave about 0.11.
        let f = failure_strain("al7075").unwrap();
        assert_eq!(f.basis, Basis::Typical);
        assert!((f.value - 0.104).abs() < 0.01, "{}", f.value);
        // Every 2024 / 7075 / 2014 handbook condition with an elongation is Validated.
        let validated = builtin_catalog().filter(|m| m.extra.is_some_and(|x| ["2014", "2024", "7075"].iter().any(|a| x.alloy.starts_with(a))) && failure_strain(m.id).unwrap().basis == Basis::Validated).count();
        assert!(validated > 100, "{validated}");
    }
}
